// The data the package ships, generated by scripts (not by hand).
import zoneData from "./zones.json" with { type: "json" };

/**
 * The time zone names definitions may use (specification section 6.3), with the version of the tz
 * database they came from. Generated by `pnpm zones`.
 */
export const zones: {
  tzdb: string;
  node: string;
  osTzdata: string | null;
  names: readonly string[];
} = {
  tzdb: zoneData.tzdb,
  node: zoneData.node,
  osTzdata: zoneData.osTzdata,
  names: zoneData.zones,
};
